package com.yeyamo_mobile.api.notification_service.infrastructure.persistence;
import java.util.*;import org.springframework.stereotype.Component;import com.yeyamo_mobile.api.notification_service.application.port.PreferenceRepositoryPort;import com.yeyamo_mobile.api.notification_service.domain.NotificationPreference;
@Component public class JpaPreferenceAdapter implements PreferenceRepositoryPort{private final SpringPreferenceRepository repo;public JpaPreferenceAdapter(SpringPreferenceRepository r){repo=r;}public Optional<NotificationPreference>find(String id){return repo.findById(id).map(this::domain);}public NotificationPreference save(NotificationPreference p){PreferenceEntity e=repo.findById(p.userId()).orElseGet(PreferenceEntity::new);e.userId=p.userId();e.inAppEnabled=p.inAppEnabled();e.emailEnabled=p.emailEnabled();e.pushEnabled=p.pushEnabled();e.emailAddress=p.emailAddress();e.pushToken=p.pushToken();e.locale=p.locale();e.updatedAt=p.updatedAt();return domain(repo.save(e));}private NotificationPreference domain(PreferenceEntity e){return new NotificationPreference(e.userId,e.inAppEnabled,e.emailEnabled,e.pushEnabled,e.emailAddress,e.pushToken,e.locale,e.updatedAt);}}
